#include <algorithm>
using namespace std;

const int MAXN = 210;
const int INF = 0x3f3f3f3f;

struct MaxFlow {
    int capacity[MAXN][MAXN], flow[MAXN][MAXN], adj[MAXN][MAXN], degree[MAXN];
    int nodeCount, source, sink;
    int height[MAXN], countHeight[MAXN], visited[MAXN], mark[MAXN];

    void initialize(int n) {
        nodeCount = n;
        memset(capacity, 0, sizeof(capacity));
        memset(adj, 0, sizeof(adj));
        memset(mark, 0, sizeof(mark));
        for (int i = 0; i <= n; i++) degree[i] = 0;
    }

    void addEdge(int u, int v, int cap) {
        capacity[u][v] += cap;
        adj[u][v] = 1;
        if (!adj[u][v]) { adj[u][v] = 1; degree[u]++; }
    }

    int sendFlow(int u, int flowIn) {
        if (u == sink) return flowIn;
        int totalFlow = 0;
        for (int v = 0; v < nodeCount; v++) {
            if (capacity[u][v] - flow[u][v] > 0 && height[u] == height[v] + 1) {
                int currFlow = min(flowIn, capacity[u][v] - flow[u][v]);
                int tempFlow = sendFlow(v, currFlow);
                if (tempFlow > 0) {
                    flow[u][v] += tempFlow;
                    flow[v][u] -= tempFlow;
                    totalFlow += tempFlow;
                    flowIn -= tempFlow;
                    if (flowIn == 0) break;
                }
            }
        }
        if (totalFlow == 0) {
            int minH = nodeCount;
            for (int v = 0; v < nodeCount; v++) {
                if (capacity[u][v] - flow[u][v] > 0) minH = min(minH, height[v]);
            }
            if (--countHeight[height[u]] == 0) height[source] = nodeCount;
            height[u] = minH + 1;
            countHeight[height[u]]++;
        }
        return totalFlow;
    }

    int maxFlow(int s, int t) {
        source = s; sink = t;
        memset(flow, 0, sizeof(flow));
        memset(height, 0, sizeof(height));
        memset(countHeight, 0, sizeof(countHeight));
        for (int i = 0; i < nodeCount; i++) height[i] = 0;
        countHeight[0] = nodeCount;
        int total = 0;
        while (height[source] < nodeCount) {
            total += sendFlow(source, INF);
        }
        return total;
    }
};

struct Node {
    int x, y, step;
};

int n, t;
int startX, startY;
int dx[4] = {0, 0, -1, 1};
int dy[4] = {-1, 1, 0, 0};
char grid1[210][210], grid2[210][210];
int distFlag[210][210], visited[210][210];

int ID(int i, int j) {
    return (i - 1) * n + j;
}

bool valid(int x, int y) {
    return x >= 1 && x <= n && y >= 1 && y <= n;
}

void BFS1() {
    queue<Node> q;
    Node current, next;
    current.x = startX; current.y = startY; current.step = 0;
    q.push(current);
    memset(distFlag, 0x7f, sizeof(distFlag));
    memset(visited, 0, sizeof(visited));
    visited[startX][startY] = 1;
    while (!q.empty()) {
        current = q.front(); q.pop();
        distFlag[current.x][current.y] = current.step;
        if (current.step > t) break;
        for (int k = 0; k < 4; k++) {
            int nx = current.x + dx[k], ny = current.y + dy[k];
            if (valid(nx, ny) && grid1[nx][ny] != 'Y' && !visited[nx][ny]) {
                next.x = nx; next.y = ny; next.step = current.step + 1;
                visited[nx][ny] = 1;
                q.push(next);
            }
        }
    }
}

void BFS2(int i, int j) {
    queue<Node> q;
    Node current, next;
    current.x = i; current.y = j; current.step = 0;
    memset(visited, 0, sizeof(visited));
    visited[i][j] = 1;
    q.push(current);
    while (!q.empty()) {
        current = q.front(); q.pop();
        if (current.step > t) break;
        if (distFlag[current.x][current.y] < current.step) continue;
        if ((distFlag[current.x][current.y] == current.step && (grid2[current.x][current.y] < '1' || grid2[current.x][current.y] > '9'))) continue;
        if (grid2[current.x][current.y] >= '1' && grid2[current.x][current.y] <= '9') {
            if (current.x != i || current.y != j)
                maxFlow.addEdge(ID(i, j), ID(current.x, current.y) + n * n, INF);
            if (distFlag[current.x][current.y] == current.step) continue;
        }
        for (int k = 0; k < 4; k++) {
            int nx = current.x + dx[k], ny = current.y + dy[k];
            if (valid(nx, ny) && grid1[nx][ny] != 'Y' && !visited[nx][ny]) {
                next.x = nx; next.y = ny; next.step = current.step + 1;
                visited[nx][ny] = 1;
                q.push(next);
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 1; i <= n; i++) scanf("%s", grid1[i] + 1);
    for (int i = 1; i <= n; i++) scanf("%s", grid2[i] + 1);
    int s = 0, e = 2 * n * n + 1;
    maxFlow.initialize(e + 1);
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (grid1[i][j] >= '1' && grid1[i][j] <= '9') {
                maxFlow.addEdge(s, ID(i, j), grid1[i][j] - '0');
            }
            if (grid1[i][j] == 'Z') {
                startX = i; startY = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            maxFlow.addEdge(ID(i, j), ID(i, j) + n * n, INF);
            if (grid2[i][j] >= '1' && grid2[i][j] <= '9') {
                maxFlow.addEdge(ID(i, j) + n * n, e, grid2[i][j] - '0');
            }
        }
    }
    BFS1();
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (grid1[i][j] >= '1' && grid1[i][j] <= '9') BFS2(i, j);
        }
    }
    int result = maxFlow.maxFlow(s, e);
    printf("%d\n", result);
}
